---- MY PROGRAMS ----
---------------------

-- Set programs that you use
local terminal    = "ghostty"
local fileManager = "dolphin"
local menu        = "wofi --show drun"
local browser     = "google-chrome-stable"


-------------------
---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/configuring/core/autostart/

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
--
-- hl.on("hyprland.start", function ()
--   hl.exec_cmd(terminal)
--   hl.exec_cmd("nm-applet")
--   hl.exec_cmd("waybar & hyprpaper & firefox")
-- end)

hl.on("hyprland.start", function()
    hl.exec_cmd(terminal)
    -- NOTE: you start BOTH hyprpaper and awww as wallpaper daemons; they fight
    -- over the background. Pick one and delete the other line.
    hl.exec_cmd("waybar & hyprpaper")
    -- hl.exec_cmd("awww-daemon & awww img ~/Downloads/a_street_with_a_building_and_a_moon_in_the_sky.png")
    hl.exec_cmd("blueman-applet")
    -- hl.exec_cmd("nm-applet")
end)


