---------------------
---- KEYBINDINGS ----
---------------------

local mainMod = "SUPER"
local function key(k) return mainMod .. " + " .. k end

hl.bind(key("SHIFT + Q"), hl.dsp.exec_cmd(terminal))
hl.bind(key("SHIFT + C"), hl.dsp.window.close())
hl.bind(key("SHIFT + M"), hl.dsp.exit())
hl.bind(key("E"), hl.dsp.exec_cmd(fileManager))
-- hl.bind(key("SHIFT + V"), hl.dsp.window.float({ action = "toggle" }))
hl.bind(key("R"), hl.dsp.exec_cmd(menu))
hl.bind(key("P"), hl.dsp.window.pseudo())               -- dwindle
hl.bind(key("SHIFT + T"), hl.dsp.layout("togglesplit")) -- dwindle
hl.bind(key("SHIFT + B"), hl.dsp.exec_cmd(browser))
hl.bind(key("SHIFT + S"), hl.dsp.exec_cmd("steam"))
hl.bind(key("SHIFT + D"), hl.dsp.exec_cmd("discord"))
hl.bind(key("SHIFT + O"), hl.dsp.exec_cmd("obsidian"))

hl.bind(key("SHIFT + TAB"), hl.dsp.window.swap({ direction = "left" }))
hl.bind(key("TAB"), hl.dsp.window.cycle_next())

-- Focus: arrows + vim keys
for k, dir in pairs({ left = "left", H = "left", right = "right", L = "right",
    up = "up", K = "up", down = "down", J = "down" }) do
    hl.bind(key(k), hl.dsp.focus({ direction = dir }))
end

-- Workspaces 1-10 (key 0 -> 10)
for i = 1, 10 do
    local n = i % 10
    hl.bind(key(n), hl.dsp.focus({ workspace = i }))
    hl.bind(key("SHIFT + " .. n), hl.dsp.window.move({ workspace = i }))
end

-- Scratchpad (you had ALT+S for move; kept, since SHIFT+S is Steam)
hl.bind(key("S"), hl.dsp.workspace.toggle_special("magic"))
hl.bind(key("ALT + S"), hl.dsp.window.move({ workspace = "special:magic" }))

-- Scroll through existing workspaces
hl.bind(key("mouse_down"), hl.dsp.focus({ workspace = "e+1" }))
hl.bind(key("mouse_up"), hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize with mouse
hl.bind(key("mouse:272"), hl.dsp.window.drag(), { mouse = true })
hl.bind(key("mouse:273"), hl.dsp.window.resize(), { mouse = true })

-- Laptop multimedia keys for volume and LCD brightness
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"),
    { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),
    { locked = true, repeating = true })
hl.bind("XF86AudioMute", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),
    { locked = true, repeating = true })
hl.bind("XF86AudioMicMute", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),
    { locked = true, repeating = true })
hl.bind("XF86MonBrightnessUp", hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%+"), { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%-"), { locked = true, repeating = true })

-- Requires playerctl
hl.bind("XF86AudioNext", hl.dsp.exec_cmd("playerctl next"), { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev", hl.dsp.exec_cmd("playerctl previous"), { locked = true })

-- Screenshot (region -> file + clipboard)
hl.bind("ALT + SHIFT + 4",
    hl.dsp.exec_cmd([[grim -g "$(slurp)" - | tee ~/Pictures/screenshot-$(date +%F-%T).png | wl-copy]]))

--------------------------------
---- WINDOWS AND WORKSPACES ----
--------------------------------

-- See https://wiki.hypr.land/configuring/core/rules/

-- Example window rules that are useful

local suppressMaximizeRule = hl.window_rule({
    -- Ignore maximize requests from all apps. You'll probably like this.
    name           = "suppress-maximize-events",
    match          = { class = ".*" },

    suppress_event = "maximize",
})
-- suppressMaximizeRule:set_enabled(false)

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name     = "fix-xwayland-drags",
    match    = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})

